{
  "check_id": "CHK-W4B13-51-002",
  "title": "Does the P2P peer actor correctly validate incoming ENR eth2 fields for BPO fork compatibility?",
  "severity": "Medium",
  "property_id": "PROP-W4B13-51",
  "bug_class": "Input Validation",
  "risk_category": "Denial of Service",
  "test_procedure": "1. Locate the ENR validation logic in the P2P peer handling code.
2. Verify that BPO fork detection correctly identifies when a fork is BPO vs. regular.
3. Test that peers with correctly computed BPO fork ENR eth2 fields are accepted.
4. Test that peers with incorrectly computed ENR eth2 fields (next_fork_version != current_fork_version for BPO) are handled appropriately.
5. Verify the validation logic does not inadvertently reject compatible peers at BPO fork boundaries.",
  "code_excerpt": "// From beacon-chain/p2p/fork.go
func compareForkENR(self, peer *enr.Record) error {
	peerEntry, err := forkEntry(peer)
	if err != nil {
		return err
	}
	selfEntry, err := forkEntry(self)
	if err != nil {
		return err
	}
	peerString, err := SerializeENR(peer)
	if err != nil {
		return err
	}
	if !bytes.Equal(peerEntry.CurrentForkDigest, selfEntry.CurrentForkDigest) {
		return errors.Wrapf(errCurrentDigestMismatch, ...)
	}
	if peerEntry.NextForkEpoch != selfEntry.NextForkEpoch {
		log.WithFields(logrus.Fields{...}).Trace("Peer matches fork digest but has different next fork epoch")
		return nil // Allow connection - different view of next fork
	}
	if !bytes.Equal(peerEntry.NextForkVersion, selfEntry.NextForkVersion) {
		return errors.Wrapf(errNextVersionMismatch, ...)
	}
	// Fulu nfd check
	if !params.FuluEnabled() {
		return nil
	}
	peerNFD, selfNFD := nfd(peer), nfd(self)
	if peerNFD != selfNFD {
		return errors.Wrapf(errNextDigestMismatch, ...)
	}
	return nil
}

// From config/params/config.go
func entryWithForkDigest(entry NetworkScheduleEntry, b *BeaconChainConfig) (NetworkScheduleEntry, error) {
	root, err := computeForkDataRoot(entry.ForkVersion, b.GenesisValidatorsRoot)
	if err != nil {
		return entry, err
	}
	entry.ForkDigest = to4(root[:])
	if entry.Epoch < b.FuluForkEpoch {
		return entry, nil
	}
	hb := make([]byte, 16)
	binary.LittleEndian.PutUint64(hb[0:8], uint64(entry.BPOEpoch))
	binary.LittleEndian.PutUint64(hb[8:], entry.MaxBlobsPerBlock)
	bpoHash := hash.Hash(hb)
	entry.ForkDigest[0] = entry.ForkDigest[0] ^ bpoHash[0]
	entry.ForkDigest[1] = entry.ForkDigest[1] ^ bpoHash[1]
	entry.ForkDigest[2] = entry.ForkDigest[2] ^ bpoHash[2]
	entry.ForkDigest[3] = entry.ForkDigest[3] ^ bpoHash[3]
	return entry, nil
}",
